/* 19. Exact fix: Claude's "bg-page" backing and the transcript-bottom-backing
   pieces under the composer dock (v1.0.7). They keep their job of hiding the
   transcript behind the dock, but are painted with the SAME fixed grid wallpaper
   as the page, so they blend in seamlessly instead of showing a gray bar. */
.bg-page, [class*="bg-page"],
[data-testid^="transcript-bottom-backing"], [data-testid*="backing"] {
  background-color: #0a0a0a !important;
  background-image:
